93	fn set_validators(
94	    deps: DepsMut,
95	    env: &Env,
96	    validators: BTreeMap<Addr, Uint128>,
97	) -> Result<Response, ContractError> {
98	    let validators = validators
99	        .into_iter()
100	        .map(|(k, v)| (k.into(), v.into()))
101	        .collect();
102	
103	    let is_first = deps.storage.maybe_read_item::<Validators>()?.is_none();
104	
105	    deps.storage.write_item::<Validators>(&validators);
106	
107	    let total_shares = validators.values().try_fold(0_u128, |total, shares| {
108	        total
109	            .checked_add(*shares)
110	            .ok_or(ContractError::TooManyShares)
111	    })?;
112	
113	    let mut response = Response::new()
114	        .add_event(SetValidators { total_shares })
115	        .add_events(
116	            validators
117	                .iter()
118	                .map(|(validator, shares)| ValidatorConfigured {
119	                    address: validator,
120	                    shares: *shares,
121	                    weight: Decimal256::from_ratio(*shares, total_shares),
122	                }),
123	        );
124	
125	    // if this isn't the first time setting the validators, rebase and rebalance the currently
126	    // staked amounts
127	    if !is_first {
128	        let rebase_response = rebase(deps.as_ref(), env)?;
129	
130	        let native_token_denom = query_native_token_denom(deps.as_ref())?;
131	
132	        let current_delegations = deps
133	            .querier
134	            .query_all_delegations(env.contract.address.clone())?
135	            .into_iter()
136	            .filter(|s| s.amount.denom == native_token_denom)
137	            .map(|s| (s.validator, s.amount.amount.u128()))
138	            .collect();
139	
140	        let redelegation_msgs =
141	            redisribute_delegations(&native_token_denom, current_delegations, validators.clone())?;
142	
143	        response = response
144	            .add_events(rebase_response.events)
145	            .add_submessages(rebase_response.messages)
146	            .add_messages(redelegation_msgs);
147	    }
148	
149	    Ok(response)
150	}
