/// Send the unstaked native tokens of a submitted batch back to the LST hub.
///
/// The unbonded native tokens are returned to this contract by the staking module once the
/// unbonding period elapses, so this simply forwards the batch's expected amount back to the hub via
/// [`lst::msg::ExecuteMsg::ReceiveUnstakedTokens`].
fn receive_unstaked_tokens(deps: Deps, batch_id: BatchId) -> Result<Response, ContractError> {
    let hub = deps.storage.read_item::<LstHub>()?;

    let native_token_denom = query_native_token_denom(deps)?;

    let expected_native_unstaked = match deps
        .querier
        .query_wasm_smart::<Option<Batch>>(&hub, &lst::msg::QueryMsg::Batch { batch_id })?
    {
        Some(Batch::Submitted(batch)) => batch.expected_native_unstaked,
        _ => {
            return Err(StdError::generic_err(format!(
                "batch {batch_id} is not in a submitted state"
            ))
            .into());
        }
    };

    Ok(Response::new().add_message(wasm_execute(
        hub,
        &lst::msg::ExecuteMsg::ReceiveUnstakedTokens { batch_id },
        vec![Coin::new(expected_native_unstaked, native_token_denom)],
    )?))
